def summarize(cases) -> list[dict]:
    return [
        {"case": c.case_id, "evidence": len(c.evidence)}
        for c in cases
    ]

@app.get("/cases/summary")
def summary(
    limit: int = 20,
    session: Session = Depends(get_session),
) -> list[dict]:
    query = select(CaseRow).limit(limit)
    return summarize(session.scalars(query))
